function renderChoiceText(){renderInteractionControls();const icon=$('#choice-action-icon'),iconKey=mode==='belongings'?uiBelongingChoices(state)[choice]?.action[0]||'room':mode==='food'?'feed':mode;paintIcon(icon.getContext('2d'),iconKey,2);const portrait=$('#choice-portrait');portrait.width=128;portrait.height=100;if(worldModes.includes(mode)){renderWorldChoice(portrait);return;}if(['food','memory','room','routine','adventure','tree'].includes(mode)){renderCompanionChoice(portrait);return;}portrait.hidden=mode==='games';if(mode==='games'){$('#choice-title').textContent=(choice+1)+'/4 · '+gameTypes[choice].name;$('#choice-detail').textContent=gameTypes[choice].hint+'\n5 успіхів · до 3 помилок · +3 монети';return;}if(mode==='family'){const partner=candidates(state)[choice];$('#choice-title').textContent=partner.name+' · '+traits[partner.trait].name;$('#choice-detail').textContent=(choice+1)+'/3 · '+species.find(p=>p.id===partner.species).name+'\nОК — обрати пару й підтвердити нове яйце';draw(portrait,partner.species,0,{...state,name:partner.name,portraitStage:'Дорослий',appearance:partner.appearance,trait:partner.trait,sleeping:false,napping:false,poop:0},false);return;}const row=albumRecords[albumIndex];portrait.hidden=!row;if(!row){$('#choice-title').textContent='Альбом ще порожній';$('#choice-detail').textContent='Тут залишаться портрети й історії попередніх друзів. ↶ — повернутися';return;}$('#choice-title').textContent=row.name+' · покоління '+row.generation;const duration=row.ageMs/86400000;$('#choice-detail').textContent=(albumIndex+1)+' · '+(row.outcome==='family'?'Нове покоління ♥':'На веселці ♡')+'\n'+row.stage+' · '+(duration<1?Math.floor(row.ageMs/60000)+' хв':duration.toFixed(1)+' діб')+'\n'+row.character+' · '+(traits[row.trait]?.name||'Буркотун')+(row.partner?'\nПара: '+row.partner.name:'')+'\n\nЛистівка: «'+(row.farewell?.text||farewell(row,row.outcome).text)+'»';draw(portrait,row.species,0,portraitState(row),false);}
async function openAlbum(){if(busy)return;mode='album';albumIndex=0;busy=true;render();try{if(online){const r=await api('album');albumRecords=r.records;albumCursor=r.cursor;albumMore=r.hasMore;}else{if(state?.dead)rememberLocal(state,state.endReason||'death');albumRecords=localAlbum();albumMore=false;}}catch(e){fail(e.message);}finally{busy=false;render();}}
async function moveAlbum(direction){if(busy)return;if(direction>0&&albumIndex===albumRecords.length-1&&albumMore&&online){busy=true;render();try{const r=await api('album',{cursor:albumCursor});albumRecords.push(...r.records);albumCursor=r.cursor;albumMore=r.hasMore;}catch(e){fail(e.message);}finally{busy=false;}}if(albumRecords.length)albumIndex=Math.max(0,Math.min(albumRecords.length-1,albumIndex+direction));render();}
async function createFamily(){if(busy)return;busy=true;generation++;render();try{const partner=candidates(state)[choice],parentBefore={...state,portraitStage:'Дорослий',sleeping:false,napping:false,poop:0};const result=online?await api('family',{partnerId:partner.id}):nextGeneration(state,partner.id);if(result.error)throw Error(result.error);if(!online)rememberLocal(state,'family',result.record);const parentCanvas=document.createElement('canvas'),partnerCanvas=document.createElement('canvas');for(const c of [parentCanvas,partnerCanvas]){c.width=128;c.height=100;}drawBase(parentCanvas,parentBefore.species,0,parentBefore,true);drawBase(partnerCanvas,partner.species,0,{...parentBefore,trait:partner.trait},true);familyScene={parent:parentCanvas,partner:partnerCanvas,until:Date.now()+3000};state=result.state;effect=null;if(!online)save();picked=0;speak(result.text);void audio.react('adopt',state.species);}catch(e){fail(e.message);}finally{busy=false;mode='normal';render();}}
async function load(){if(loading||busy||choosingNew)return;loading=true;const revision=generation;render();let greeting=null;try{if(online){const r=await api('state',{roomReturn:true});greeting=r.greeting;if(revision===generation)state=r.state;}else{try{const raw=JSON.parse(localStorage.getItem('hamagochi-v1'));if(raw&&species.some(s=>s.id===raw.species)&&['born','updated','hunger','happy','energy','clean','health','coins','xp'].every(k=>Number.isFinite(raw[k])))state=tick(raw);}catch{}}if(state&&!online){if(state.cozy)state.cozy.hide=null;if(state.lively)state.lively.secret=null;greeting=visit(state);save();}if(state)speak(state.dead?'На веселці тепло. ОК — обрати нового друга.':state.sleeping?'Тихенько. Я ще дрімаю.':greeting||'О, моя людина! '+traits[traitOf(state)].line);}catch(e){fail(e.message);}finally{loading=false;render();}}
let previous=0;function animate(t){if(t-previous>80){draw($('#pet'),state?.species||selected,t,state);if(state&&journalModes.includes(mode))renderJournalCanvas($('#choice-portrait'));if(state&&mode==='sandbox')drawSandbox($('#choice-portrait'));if(state&&!sceneModes.has(mode)&&worldModes.includes(mode)&&!['world','photos','sandbox','wallet','roomStyle','belongings',...journalModes].includes(mode)){if(mode==='hide'&&state.cozy?.hide?.expires>Date.now()&&detailedReady()){drawDetailedMain($('#choice-portrait'),state,state.species,t,reduced,null,effect);}else if(mode==='hide'&&state.cozy?.hide?.expires>Date.now()){const cv=$('#choice-portrait');cv.width=192;cv.height=144;drawExpandedRoom(cv.getContext('2d'),state,t,reduced);drawHideClue(cv.getContext('2d'),state);}else draw($('#choice-portrait'),state.species,t,state);}if(state&&sceneModes.has(mode))renderMenuScene(t);bounce*=.65;previous=t;}requestAnimationFrame(animate);}requestAnimationFrame(animate);
setInterval(async()=>{if(!state||busy||loading||networkClient.busy()||mode!=='normal'||document.hidden)return;const revision=generation;if(online){try{const r=await api('state',{}, {background:true});if(!r)return;if(revision!==generation||busy||mode!=='normal'||choosingNew)return;state=r.state;if(r.greeting)speak(r.greeting);}catch{return;}}else{state=tick(state);save();}render();if(state&&!state.dead&&!effectActive()){const urgent=Math.min(state.health,state.hunger,state.energy)<20?needs(state):null;if(urgent&&Date.now()-lastSpeech>15000)speak(urgent.text);else if(idleSpeechDue(state,lastSpeech))speak(idleSpeech(state));}},30000);
document.addEventListener('visibilitychange',()=>{if(document.hidden){void audio.suspend();if(game)endGame(false,true);}else if(!busy&&mode==='normal')void load();});render();void load();

let displayedStage=state?stage(state):null,displayedBorn=state?.born;
setInterval(()=>{if(!state||state.dead)return;const removed=state.cozy?.lastRemoved?.at;updateCozy(state);if(state.cozy?.lastRemoved?.at!==removed){if(!online)save();speak('Зняв незручний одяг. Давай приміряємо щось інше, людино?');if(mode==='wardrobe'&&!busy)render();}const current=stage(state);if(displayedBorn===state.born&&displayedStage&&displayedStage!==current){speak(current==='Малюк'?'Трісь! Я вилупився. Де моя людина й обійми?':current==='Дитина'?'Я виспався й підріс. Дивися, які лапки!':current==='Підліток'?'Я вже підліток. Характер росте швидше за лапки.':current==='Старенький'?'Я вже старенький. Посидь зі мною, моя людино.':'Я дорослий! Але на ручки все одно хочу.');void audio.react('adopt',state.species);}displayedStage=current;displayedBorn=state.born;if(mode==='normal'&&!busy)render();},1000);

async function toggleReminders(){
 if(!online){speak('Нагадування доступні в Telegram. Відкрий гру з бота.');return;}
 if(busy)return;
 busy=true;render();try{
 if(!remindersEnabled){
 if(typeof tg.requestWriteAccess!=='function')throw new Error('Онови Telegram, щоб дозволити повідомлення від пета.');
 const allowed=await new Promise(resolve=>{const timeout=setTimeout(()=>resolve(false),60000);tg.requestWriteAccess(ok=>{clearTimeout(timeout);resolve(ok);});});
 if(!allowed){speak('Без дозволу не писатиму. Увімкнути можна пізніше.');return;}
 }
 const timezone=Intl.DateTimeFormat().resolvedOptions().timeZone||'Europe/Kyiv';
 const r=await api('reminders',{enabled:!remindersEnabled,timezone});speak(r.text);$('#error').hidden=true;
 }catch(e){fail(e.message);}finally{busy=false;render();}
}

function renderCompanionChoice(portrait){portrait.hidden=true;const title=$('#choice-title'),detail=$('#choice-detail');
 if(mode==='food'){const list=foodsFor(state,stage(state)),food=list[choice];title.textContent=(choice+1)+'/'+list.length+' · '+foodNames[food];detail.textContent=(state.memory?.discoveries.includes(food)?'♡ Уже знаємо: це улюблена їжа!':'Який смак оберемо сьогодні?')+'\nОК — погодувати';return;}
 if(mode==='memory'){title.textContent=state.name+' пам’ятає';detail.textContent=memorySummary(state)+(state.memory.lastAdventure?'\nПригода: '+state.memory.lastAdventure.title:'')+(state.heirloom?'\nСпадок: '+state.heirloom.name:'');return;}
 if(mode==='room'){const item=furnishings[choice],owned=state.room?.[item.id];title.textContent=item.name+(owned?' · Є В КІМНАТІ':' · '+item.price+' монет');detail.textContent=item.benefit+'\n'+(owned?'ОК — скористатися':'ОК — придбати');portrait.hidden=false;if(detailedReady()){drawDetailedMain(portrait,state,state.species,0,true,{x:96,feet:128,scale:1},null);}else{const c=portrait.getContext('2d');c.clearRect(0,0,128,100);drawHome(c,state,0);}return;}
 if(mode==='routine'){const [field,name]=routineFields[choice];title.textContent=name;detail.textContent=(field==='enabled'?(state.routine.enabled?'УВІМКНЕНО':'ВИМКНЕНО'):String(state.routine[field]).padStart(2,'0')+':00')+'\nОК — '+(field==='enabled'?'увімкнути / вимкнути':'додати 1 годину')+'\n← → інший пункт · ↶ назад';return;}
 if(mode==='adventure'){const event=adventureOf(state);title.textContent=event?.title||'Зараз спокійно';detail.textContent=event?event.question+'\n▶ '+event.choices[choice].label+'\nОК — відповісти':'Пригоди часом трапляються самі. А поки можна обійнятися.';return;}
 if(mode==='tree'){const row=treeRecords[treeIndex];title.textContent=row?row.name+' · покоління '+row.generation:'Родинне дерево';detail.textContent=row?((row.parents?.length?'Батьки: '+row.parents.map(p=>p.name).join(' + '):'Початок цієї гілки родини')+(row.heirloom?'\nСпадок: '+row.heirloom.name+' від '+row.heirloom.from:'')+'\n'+(treeIndex+1)+'/'+treeRecords.length+' · ← → родичі'):'У нас ще все попереду.';return;}
}
async function companion(command,body={},stay=false){if(busy||!state)return;busy=true;generation++;$('#error').hidden=true;render();try{const r=online?await api('companion',{command,...body}):performCompanion(state,command,body);if(r.error)throw Error(r.error);state=r.state;if(!online)save();if(!['toyTurn','activityStep','cookStep'].includes(command)||!state.playroom?.session&&!state.world?.activity&&!state.cozy?.cooking)speak(r.text);if(r.effect){effect={kind:r.effect,started:Date.now(),until:Date.now()+2000};void audio.react('play',state.species);}if(!stay)mode='normal';}catch(e){fail(e.message);}finally{busy=false;render();}}
async function useRoom(){const item=furnishings[choice];if(!state.room[item.id]){await companion('roomBuy',{item:item.id},false);return;}if(item.id==='bed'){mode='normal';await action('sleep');}else if(item.id==='bowl'){mode='food';choice=0;render();}else if(item.id==='toy'){if(state.vacation||state.sleeping||state.napping||stage(state)==='Яєчко'){speak('Пограємо, коли друг буде вдома й прокинеться.');return;}mode='toys';choice=0;render();}else await companion('roomUse',{item:item.id});}
async function openTree(){if(busy)return;busy=true;treeIndex=0;mode='tree';render();try{treeRecords=online?(await api('tree')).records:lineageRows(state,localAlbum());}catch(e){fail(e.message);}finally{busy=false;render();}}

function idleSpeech(s){const intro=introHint(s);if(intro)return intro;if(s.vacation)return 'Відпочиваю в готелі. Твої обійми заброньовані.';if(s.sleeping||s.napping)return s.world?.dream?'Сниться: '+s.world.dream.title+'…':'Хрр… обійми… хрр…';const story=wakeStory(s);if(story){if(!online)save();return story;}if(s.world?.wakeStoryPending===false&&s.world?.lastDream&&Date.now()-s.world.lastDream.wokeAt<30000)return s.world.lastDream.text;if(s.cozy?.lastRemoved&&Date.now()-s.cozy.lastRemoved.at<120000)return 'Зняв '+(clothes.find(i=>i.id===s.cozy.lastRemoved.id)?.name||'одяг').toLowerCase()+'. Мені незручно. Давай іншу річ?';const invitation=relationshipHint(s);if(invitation)return invitation;const urgent=needs(s);if(urgent)return urgent.text;const moment=roomMoment(s);if(moment?.auto&&Math.random()<.7)return roomLine(s,moment.item);const auto=ambient(s);if(auto?.text&&(['hum','dance','thought'].includes(auto.kind)||Math.random()<.6))return auto.text;const daily=dailyHint(s);if(daily&&Math.random()<.5)return daily;const ritual=ritualHint(s);if(ritual&&Math.random()<.3)return ritual;const hint=routineHint(s);if(hint)return hint;if(s.adventure)return 'У мене маленька пригода! Заглянь у ◇.';const need=needs(s);if(need)return need.text;if(s.hunger<25)return line('hungry',s.species);if(s.clean<25)return line('dirty',s.species);return chooseDialogue(s);}

function renderWorldChoice(portrait){if(mode==='wallet'){portrait.hidden=true;$('#choice-title').textContent='ГАМАНЕЦЬ І ПОДАРУНКИ';$('#choice-detail').textContent=walletInfo?'У гаманці: '+walletInfo.balance+' монет.\nУ кишені пета: '+state.coins+'.\nТвій Telegram ID: '+walletInfo.telegramId+'\n'+(walletInfo.owner?'Власника розпізнано ✓':walletInfo.ownerConfigured?'ID власника не збігається з цією Telegram-сесією.':'Секрет OWNER_TELEGRAM_ID не задано у цьому Worker.')+'\nДля покупок переведи монети в кишеню пета. Гаманець зберігається між поколіннями.':'Завантажую гаманець…';renderWallet();return;}if(mode==='roomStyle'){const [kind,index]=styleOptions()[choice],item=roomStyles[kind][index];paintPhotoScene(portrait,{...state,roomMood:{...state.roomMood,[kind]:item.id}});portrait.hidden=false;$('#choice-title').textContent=styleFields.find(x=>x[0]===kind)[1]+': '+item.name;$('#choice-detail').textContent=(state.roomMood?.owned?.[kind]?.includes(item.id)||item.price===0?'Придбано · ОК — обрати':item.price+' монет · ОК — придбати й обрати')+'\n'+styleOpinion(state,{...state.roomMood,[kind]:item.id})+'\n← → всі шпалери, підлоги та лампи';return;}if(journalModes.includes(mode)){renderJournalChoice(portrait);return;}if(cozyPages.some(([id])=>id===mode)){renderCozyChoice(portrait);return;}if(playroomPages.some(([id])=>id===mode)){renderPlayroomChoice(portrait);return;}if(dailyPages.some(([id])=>id===mode)){renderDailyChoice(portrait);return;}
 const title=$('#choice-title'),detail=$('#choice-detail'),w=state.world||{};portrait.hidden=mode==='world';if(!portrait.hidden){draw(portrait,state.species,Date.now(),state);}
 if(mode==='secrets'){portrait.hidden=false;draw(portrait,state.species,Date.now(),state);title.textContent='СЕКРЕТИ КІМНАТИ';const spots=['window','box','plant'],spot=spots[choice%3];detail.textContent=['Постукати у вікно','Пошурхотіти коробкою','Зазирнути в рослинку'][choice%3]+(state.lively?.found?.[spot]?' · ЗНАЙДЕНО':' · ???')+'\nОК — дослідити. Деякі секрети люблять кілька дотиків.';return;}if(mode==='sandbox'){portrait.hidden=false;drawSandbox(portrait);title.textContent='СПІЛЬНА ПІСОЧНИЦЯ';const other=sandboxPets[Math.floor(choice/4)];detail.textContent=online?(other?other.name+(other.relationship>=3?' ♡':other.relationship<0?' …':'')+' · '+['Привітатись','Пограти разом','Побурчати','Відійти від цього пета'][choice%4]+'\n← → друг і дія · ОК · ↶ додому':'Поки тут тільки ми. Чекаємо інших гравців…'):'Відкрий гру через Telegram, щоб зустріти реальних петів.';return;}if(mode==='stories'){portrait.hidden=false;draw(portrait,state.species,Date.now(),state);title.textContent='НАША МАЛЕНЬКА ІСТОРІЯ';detail.textContent=storyView(state).title+'\n'+storyView(state).steps[Math.min(3,state.living?.story?.step||0)]+'\nОК — подбати / продовжити';return;}if(mode==='world'){title.textContent='МАЛЕНЬКИЙ СВІТ · '+(choice+1)+'/'+worldPages.length;detail.textContent='▶ '+worldPages[choice][1]+'\n← → обрати · ОК зайти';return;}
 if(mode==='ritual'){const labels=ritualOptions(state),count=w.rituals?.[choice]||0;title.textContent=labels[choice];detail.textContent='Разом робили: '+count+(count>=3&&favoriteRitual(state)===choice?' · НАШ УЛЮБЛЕНИЙ ♡':'')+'\nОК — зробити разом · ← → інший ритуал';return;}
 if(mode==='weather'){const weather=weatherAt();title.textContent=weather.name+' за вікном';detail.textContent='Ігрова погода змінюється кожні 3 години.\nДощ — ковдра, сонце — теплі щічки, гроза — схованка.\nЗвук: '+(w.weatherSound!==false?'увімкнено':'вимкнено')+' · ОК перемкнути';return;}
 if(mode==='walk'){const trip=w.walk&&w.walk.expires>Date.now()?w.walk:null;if(trip){const place=walks.find(p=>p.id===trip.place);title.textContent=place.name+' · НА ПРОГУЛЯНЦІ';detail.textContent=place.scene+'\n▶ '+place.choices[choice%2]+'\nОК — обрати';}else{title.textContent=walks[choice%walks.length].name;detail.textContent='Коротка прогулянка разом · −6 енергії\nЗнахідки, видові реакції та +настрій.\n← → місце · ОК вирушити';}return;}
 if(mode==='activity'){const run=w.activity&&w.activity.expires>Date.now()?w.activity:null;const a=activities.find(a=>a.id===run?.kind)||activities[choice%activities.length];title.textContent=(a.id==='groom'?groomName(state):a.name)+(run?' · '+(run.step+1)+'/3':'');detail.textContent=(run?activityStepText(state,a,run.step):a.hint)+'\nЗавершено разом: '+(w.skills?.[a.id]||0)+(a.id==='trick'?' · трюк: '+((w.skills?.trick||0)>=3?'вивчено':'вчимося'):'')+'\nОК — '+(run?'наступний рух':'почати');return;}
 if(mode==='dreams'){title.textContent=w.dream?'ЗАРАЗ СНІТЬСЯ':w.lastDream?'ОСТАННІЙ СОН':'СНИ ДРУГА';detail.textContent=w.dream?w.dream.title:w.lastDream?w.lastDream.title+'\n«'+w.lastDream.text+'»':'Засни хоча б на дві хвилини — і побачиш піксельний сон. Після пробудження друг розповість його.';return;}
 if(mode==='forms'){title.textContent=formNames[careForm(state)];detail.textContent='Вигляд підлітка залежить від догляду. Доросла форма закріплюється при дорослішанні.\nВисокий догляд — блиск і охайність; середній — округлість і сонні очі; низький — чубчик та скуйовджені боки.';}
}

async function worldAction(command,body={}){if(busy||!state)return;busy=true;generation++;$('#error').hidden=true;render();try{const r=online?await api('world',{command,...body}):performWorld(state,command,body);if(r.error)throw Error(r.error);state=r.state;if(!online)save();if(!['toyTurn','activityStep','cookStep'].includes(command)||!state.playroom?.session&&!state.world?.activity&&!state.cozy?.cooking)speak(r.text);if(r.effect){effect={kind:r.effect,started:Date.now(),until:Date.now()+3500};void audio.react(r.effect,state.species);}if(command==='walkStart'||command==='activityStart'||command==='walkChoice'||command==='activityStep'&&!state.world.activity)choice=0;if(command==='activityStep'&&!state.world.activity)mode='normal';}catch(e){fail(e.message);}finally{busy=false;render();}}
async function worldOK(){if(mode==='wallet'){await walletRequest('status');return;}if(mode==='roomStyle'){const [kind,index]=styleOptions()[choice];await living('roomStyle',{kind,index});return;}if(journalModes.includes(mode)){await journalOK();return;}if(mode==='sandbox'){const pet=sandboxPets[Math.floor(choice/4)];if(pet)await sandboxAction(['hello','play','tease','avoid'][choice%4],pet.id);return;}if(mode==='secrets'){await living('secret',{spot:['window','box','plant'][choice%3]});return;}if(mode==='stories'){await living('story');return;}if(cozyPages.some(([id])=>id===mode)){await cozyOK();return;}if(playroomPages.some(([id])=>id===mode)){await playroomOK();return;}if(dailyPages.some(([id])=>id===mode)){await dailyOK();return;}if(mode==='world'){mode=worldPages[choice][0];choice=0;render();if(mode==='photos')await openMoments();if(mode==='weather'&&state.world.weatherSound!==false)void audio.react(weatherAt().id,state.species);return;}if(mode==='ritual'){await worldAction('ritual',{choice});return;}if(mode==='weather'){await worldAction('weatherSound');if(state.world.weatherSound)void audio.react(weatherAt().id,state.species);return;}if(mode==='walk'){const trip=state.world.walk;if(trip&&trip.expires>Date.now())await worldAction('walkChoice',{eventId:trip.id,choice:choice%2});else await worldAction('walkStart',{place:walks[choice%walks.length].id});return;}if(mode==='activity'){const run=state.world.activity;if(run&&run.expires>Date.now())await worldAction('activityStep',{eventId:run.id});else await worldAction('activityStart',{activity:activities[choice%activities.length].id});return;}mode='world';choice=0;render();}

function dailyCount(){return Math.max(1,mode==='wishes'?3:mode==='photos'?momentRecords.length:mode==='stash'?Object.keys(state.daily?.stash||{}).filter(id=>state.daily.stash[id]>0).length:mode==='mischief'?3:mode==='celebrations'?celebrations(state).length:1);}
function renderDailyChoice(portrait){const d=state.daily||{},title=$('#choice-title'),detail=$('#choice-detail');portrait.hidden=false;
 if(mode==='photos'){const row=momentRecords[choice%Math.max(1,momentRecords.length)];if(!row){portrait.hidden=true;title.textContent='Наш фотоальбом';detail.textContent='Тут з’являться перше купання, трюк, сни, скарби й свята. Моменти зберігаються самі.';return;}const p={...row.pet,portraitStage:row.pet.portraitStage};if(row.kind==='frame'){paintPhotoScene(portrait,p);}else draw(portrait,p.species,0,p);if(!detailedReady()&&row.kind!=='frame'){drawWorld(portrait.getContext('2d'),p,p.portraitStage,{kind:row.kind,started:row.at,until:row.at+1000},row.at,true);drawDaily(portrait.getContext('2d'),p,{kind:row.kind,until:row.at+1000},row.at,true);}const frame=portrait.getContext('2d');frame.fillStyle='#e6dfc9';frame.fillRect(0,0,portrait.width,2);frame.fillRect(0,portrait.height-2,portrait.width,2);frame.fillRect(0,0,2,portrait.height);frame.fillRect(portrait.width-2,0,2,portrait.height);title.textContent=row.title;detail.textContent=new Intl.DateTimeFormat('uk-UA',{dateStyle:'short',timeStyle:'short'}).format(row.at)+' · '+(choice+1)+'/'+momentRecords.length+'\n«'+row.comment+'»\n← → фото · ОК наступне';return;}
 draw(portrait,state.species,Date.now(),state);
 if(mode==='wishes'){title.textContent='Чого хоче мій друг';detail.textContent=wishText(state)+(d.wish?'\n'+(d.wish.accepted?'Домовились! ':'')+'▶ '+wishAnswers[choice%3]:'')+(d.lastWish?'\nМинуле: '+d.lastWish.result:'');return;}
 if(mode==='stash'){const ids=Object.keys(d.stash||{}).filter(id=>d.stash[id]>0),item=treasures.find(t=>t.id===ids[choice%Math.max(1,ids.length)]);title.textContent=item?item.name+' ×'+d.stash[item.id]:'Поки порожня схованка';detail.textContent=item?'«Це мій скарб. Дуже важливий!»\nОК — покажи мені · ← → інша знахідка':'Пет знаходить дрібниці вдома й на прогулянках. З часом тут буде колекція.';return;}
 if(mode==='mischief'){title.textContent=d.mess?messNames[d.mess.kind]:'Зараз тихо. Підозріло тихо.';detail.textContent=(d.mess?'«Я просто перевіряв, як воно працює!»\n▶ '+messAnswers[choice%3]:'Друг поки нічого не накоїв.')+'\nЗвички: охайність '+(d.habits?.tidy||0)+' · пустощі '+(d.habits?.cheeky||0);return;}
 if(mode==='celebrations'){const events=celebrations(state),event=events[choice%Math.max(1,events.length)];title.textContent=event?.name||'Свята ще попереду';detail.textContent=event?(event.done?'Уже святкували! Фото є в альбомі.':'ОК — тортик, ковпачок і обійми!')+'\n← → інше свято':'Вилуплення, перший тиждень і десята прогулянка — кожен привід святкуємо разом.';return;}
 if(mode==='human'){title.textContent='Твій маленький захисник';detail.textContent=(d.kind?.text||d.lastKind?.text||'Я теж за тобою приглядаю. Поїж, перепочинь і бережи себе, моя людино.')+'\n'+(d.kind?'ОК — дякую, друже':'Немає штрафів, якщо ти зайнятий. Просто знай: я поруч.');}
}
async function openMoments(){busy=true;render();try{momentRecords=online?(await api('moments')).records:[...(state.daily?.photos||[]),...localAlbum().flatMap(r=>r.photos||[])].sort((a,b)=>b.at-a.at);choice=0;}catch(e){fail(e.message);}finally{busy=false;render();}}
async function dailyAction(command,body={}){if(busy)return false;busy=true;generation++;$('#error').hidden=true;render();try{const r=online?await api('daily',{command,...body}):performDaily(state,command,body);if(r.error)throw Error(r.error);state=r.state;if(!online)save();if(!['toyTurn','activityStep','cookStep'].includes(command)||!state.playroom?.session&&!state.world?.activity&&!state.cozy?.cooking)speak(r.text);if(r.effect){effect={kind:r.effect,started:Date.now(),until:Date.now()+4000};void audio.react(['party','treasure'].includes(r.effect)?'gift':r.effect==='human'?'blanket':r.effect==='mischief'?'play':r.effect==='shrug'?'miss':r.effect,state.species);}return true;}catch(e){fail(e.message);return false;}finally{busy=false;render();}}
async function dailyOK(){const d=state.daily;if(mode==='photos'){choice=(choice+1)%Math.max(1,momentRecords.length);render();return;}if(mode==='wishes'){if(!d.wish)return;const wish={...d.wish},answer=choice%3;if(await dailyAction('wishAnswer',{eventId:wish.id,choice:answer})){if(answer===0&&wish.kind==='walk'){mode='walk';choice=Math.max(0,walks.findIndex(p=>p.id===wish.place));render();}else if((answer<2&&wish.kind==='cuddle')||answer===1){mode='ritual';choice=0;render();}}return;}if(mode==='mischief'){if(d.mess)await dailyAction('messAnswer',{eventId:d.mess.id,choice:choice%3});return;}if(mode==='stash'){const id=Object.keys(d.stash||{}).filter(id=>d.stash[id]>0)[choice];if(id)await dailyAction('stashShow',{item:id});return;}if(mode==='celebrations'){const e=celebrations(state)[choice];if(e&&!e.done)await dailyAction('celebrate',{eventId:e.id});return;}if(mode==='human'&&d.kind)await dailyAction('humanAnswer',{eventId:d.kind.id});}

function renderPlayroomChoice(portrait){portrait.hidden=false;draw(portrait,state.species,Date.now(),state);const title=$('#choice-title'),detail=$('#choice-detail'),p=state.playroom;
 if(mode==='toys'){const run=p.session?.expires>Date.now()?p.session:null,toy=toys.find(t=>t.id===run?.kind)||toys[choice%toys.length];title.textContent=toy.name+(run?' · '+run.hits+'/'+(run.kind==='music'?3:5):p.toys[toy.id]?' · НАША':' · '+toy.price+' монет');detail.textContent=toy.hint+'\n'+(run?'↶ — завершити гру без нагороди':p.toys[toy.id]?'ОК — почати · ← → інша іграшка':'ОК — придбати · ← → інша іграшка')+'\nРазом грали: '+(p.skills[toy.id]||0)+((p.skills[toy.id]||0)>=3?' · власний прийом вивчено!':'');return;}
 if(mode==='craft'){const recipe=recipes[choice%recipes.length];title.textContent=recipe.name+(p.crafted[recipe.id]?' · ГОТОВО':'');detail.textContent=Object.entries(recipe.cost).map(([id,n])=>{const item=treasures.find(t=>t.id===id);return item.name+': '+(state.daily.stash[id]||0)+'/'+n;}).join(' · ')+'\n'+recipe.hint+'\nОК — зробити · ← → інший рецепт';return;}
 if(mode==='decorate'){const [field,name]=decorFields[choice%decorFields.length];title.textContent=name;detail.textContent=(field==='layout'?layouts[p.decor.layout]:field==='bedding'?bedding[p.decor.bedding].name:field==='display'?(treasures.find(t=>t.id===p.decor.display)?.name||'Поки без експоната'):favoriteCorner(state).name)+'\n'+(field==='corner'?'Пет сам обрав місце за характером.':'ОК — наступний варіант')+'\n← → інше налаштування';}
}
async function playroomAction(command,body={}){if(busy)return false;busy=true;generation++;$('#error').hidden=true;render();try{const r=online?await api('playroom',{command,...body}):performPlayroom(state,command,body);if(r.error)throw Error(r.error);state=r.state;if(!online)save();if(!['toyTurn','activityStep','cookStep'].includes(command)||!state.playroom?.session&&!state.world?.activity&&!state.cozy?.cooking)speak(r.text);if(r.effect){effect={kind:r.effect,started:Date.now(),until:Date.now()+3000};const sound=r.effect==='music'?'music'+(state.playroom.session?.tune||0):r.effect==='toy'?'pet':r.effect;void audio.react(sound,state.species,(state.playroom.skills.music||0)>=3);}return true;}catch(e){fail(e.message);return false;}finally{busy=false;render();}}
async function toyInput(input){const run=state.playroom.session;if(!run)return;await playroomAction('toyTurn',{eventId:run.id,input});}
async function playroomOK(){const p=state.playroom;if(mode==='toys'){if(p.session?.expires>Date.now()){await toyInput('ok');return;}const toy=toys[choice%toys.length];await playroomAction(p.toys[toy.id]?'toyStart':'toyBuy',{toy:toy.id});return;}if(mode==='craft'){await playroomAction('craft',{recipe:recipes[choice%recipes.length].id});return;}if(mode==='decorate'){const field=decorFields[choice%decorFields.length][0];if(field==='corner'){speak('Сидітиму, де зручно моїм лапкам. '+favoriteCorner(state).name+'.');return;}await playroomAction('decorate',{field});}}

function kitchenOptions(){return (dishes[state.species]||dishes.cat).flatMap(d=>additionsFor(state).map(addition=>({dish:d,addition})));}
function cozyCount(){if(mode==='shop')return homeGoods.length;if(mode==='wardrobe')return clothes.length;if(mode==='belongings')return Math.max(1,uiBelongingChoices(state).length);if(mode==='hide')return state.cozy.hide?.expires>Date.now()?hideSpots(state).length:1;if(mode==='kitchen')return state.cozy.cooking?.expires>Date.now()?1:kitchenOptions().length+1;if(mode==='peace')return 4;return 1;}
function renderCozyChoice(portrait){const c=state.cozy,title=$('#choice-title'),detail=$('#choice-detail');portrait.hidden=false;draw(portrait,state.species,Date.now(),state);
 if(mode==='shop'){const item=homeGoods[choice%homeGoods.length];title.textContent=item.name+(c.stored?.[item.id]?' · У СХОВИЩІ':c.owned[item.id]?' · ВДОМА':' · '+item.price+' монет');detail.textContent=c.stored?.[item.id]?'ОК — відкрити сховище й повернути в кімнату.':c.owned[item.id]?'Власна річ із характером. ОК — скористатися.':'Показано в кімнаті й крупним планом.\nОК — придбати · ← → інші предмети';return;}
 if(mode==='wardrobe'){const item=clothes[choice%clothes.length],owned=c.outfits[item.id],worn=c.wearing[item.slot]===item.id;title.textContent=item.name+(worn?' · НА МЕНІ':owned?' · У ГАРДЕРОБІ':' · '+item.price+' монет');detail.textContent=(itemStatus(state,item.id).known?opinionNames[opinion(state,item.id)]:'Це попередня примірка. Вподобання дізнаємось після носіння.')+'\n'+(owned?'ОК — '+(worn?'зняти':'вдягнути'):'ОК — придбати')+'\nНезручний одяг можу зняти сам. Ремонт — у «Мої речі».';return;}
 if(mode==='belongings'){const row=uiBelongingChoices(state)[choice],item=row?.item;title.textContent=item?.name||'Речі ще попереду';if(item&&!belongingItem){detail.textContent='Обери річ — потім побачиш лише її дії.\nОК — відкрити · або торкнись назви нижче';return;}if(!item){detail.textContent='Зазирни в крамничку або придбай іграшку.';return;}const status=itemStatus(state,item.id),index=((state.living?.furniture?.bed||0)+1)%variants.length,next=item.id==='bed'?{...variants[index],index}:nextDesign(state,item.id);detail.textContent=(state.cozy?.stored?.[item.id]?'У сховищі':status.known?opinionNames[opinion(state,item.id)]:'Ще знайомимося')+' · стан '+Math.round(status.wear)+'%\n▶ '+(row.action[1]+(row.action[0]==='repair'?' · 2 монети':row.action[0]==='replace'&&next?' → '+next.name+' · '+(next.price?next.price+' монет':'безкоштовно'):''))+(item.id==='bed'?'\nСон: +'+bedBonus(state).toFixed(1)+' енергії/год · '+variants[state.living?.furniture?.bed||0].name:'')+(designName(state,item.id)?'\nДизайн: '+designName(state,item.id):'')+'\n← → речі й дії · ОК';if(designsFor(item.id).length)paintPhotoScene(portrait,state);return;}
 if(mode==='hide'){const run=c.hide?.expires>Date.now()?c.hide:null;title.textContent=run?'ДЕ СХОВАВСЯ ДРУГ?':'ПОГРАЄМО В ХОВАНКИ?';detail.textContent=run?'Шукай, де щось стирчить.\n▶ '+hideSpots(state)[choice%hideSpots(state).length].name+'\nОК — перевірити':'Пет сховається за предметом у великій кімнаті.\nОК — почати · ← → обрати місце пошуку';if(run&&detailedReady()){drawDetailedMain(portrait,state,state.species,Date.now(),reduced,null,effect);}else if(run){portrait.width=192;portrait.height=144;const ctx=portrait.getContext('2d');ctx.clearRect(0,0,192,144);drawExpandedRoom(ctx,state,Date.now(),reduced);drawHideClue(ctx,state);}return;}
 if(mode==='kitchen'){if(c.cooking?.expires>Date.now()){title.textContent='ГОТУЄМО РАЗОМ · '+(c.cooking.step+1)+'/3';detail.textContent='Змішати → приготувати → скуштувати.\nОК — наступний крок';return;}const options=kitchenOptions(),option=options[choice];if(!option){title.textContent='Поповнити комору · 3 монети';detail.textContent='По 2 порції кожного продукту.\n'+ingredients.map(i=>i.name+': '+(c.pantry[i.id]||0)).join(' · ')+'\nОК — купити';return;}const key=option.dish.id+'-'+option.addition;title.textContent=option.dish.name;detail.textContent='Добавка: '+({plain:'без добавки',berry:'ягідки',greens:state.species==='frog'?'водорості':'зелень'}[option.addition])+'\nПродукти: '+ingredients.find(i=>i.id===option.dish.base).name+' ×1'+(option.addition!=='plain'?' + '+ingredients.find(i=>i.id===option.addition).name+' ×1':'')+(c.foodMemory[key]?'\n'+(isFavoriteMeal(state,option.dish.id,option.addition)?'♡ Улюблене поєднання!':'Уже куштували. Оцінка: смачно.'):'')+'\nОК — готувати · ← → рецепт';return;}
 if(mode==='peace'){title.textContent='МИР І ОБІЙМИ';detail.textContent='Образа: '+c.peace.tension+'/5 · з часом минає.\n▶ '+['Запропонувати обійми','Запропонувати гру','Тихо посидіти поруч','Мені це не подобається'][choice%4]+'\nОК — сказати';return;}
 if(mode==='night'){title.textContent='НІЧНЕ ЖИТТЯ КІМНАТИ';detail.textContent=(c.nightMode?'Увімкнено':'Вимкнено')+' · '+(isNight(state)?'Зараз ніч':'Зараз день')+'\nУночі — тихе світло, світлячки, сонне ворушіння й короткий похід по воду.\nОК — перемкнути · часовий пояс '+state.routine.timezone;}
}
async function cozyAction(command,body={}){if(busy)return false;busy=true;generation++;$('#error').hidden=true;render();try{const r=online?await api('cozy',{command,...body}):performCozy(state,command,body);if(r.error)throw Error(r.error);state=r.state;if(!online)save();if(!['toyTurn','activityStep','cookStep'].includes(command)||!state.playroom?.session&&!state.world?.activity&&!state.cozy?.cooking)speak(r.text);if(r.effect){effect={kind:r.effect,started:Date.now(),until:Date.now()+3200};void audio.react({cook:'cook',hide:'play',shrug:'miss',toy:'pet'}[r.effect]||r.effect,state.species);}return true;}catch(e){fail(e.message);return false;}finally{busy=false;render();}}
async function cozyOK(){const c=state.cozy;if(mode==='shop'){const item=homeGoods[choice%homeGoods.length];if(c.stored?.[item.id]){mode='belongings';belongingItem=item.id;choice=0;render();return;}if(c.owned[item.id]){if(await living('use',{item:item.id,...roomOrigin()})){mode='normal';render();}}else if(await cozyAction('shopBuy',{item:item.id})){mode='normal';render();}return;}if(mode==='wardrobe'){const item=clothes[choice%clothes.length];if(await cozyAction(c.outfits[item.id]?'clothesWear':'clothesBuy',{item:item.id})){mode='normal';render();}return;}if(mode==='belongings'){const row=uiBelongingChoices(state)[choice],item=row?.item;if(item){if(!belongingItem){belongingItem=item.id;choice=0;render();return;}const command=row.action[0];if(command==='putOn'){if(await cozyAction('clothesWear',{item:item.id})){mode='normal';render();}return;}if(['store','place','use','gentle','jump','rest','replace','repair'].includes(command)){const done=await living(command,{item:item.id,...roomOrigin()});if(done&&['use','gentle','jump','rest','place','replace','repair','store'].includes(command)){mode='normal';render();}}}return;}if(mode==='hide'){if(c.hide?.expires>Date.now())await cozyAction('hideGuess',{eventId:c.hide.id,spot:hideSpots(state)[choice%hideSpots(state).length].id});else await cozyAction('hideStart');return;}if(mode==='kitchen'){if(c.cooking?.expires>Date.now())await cozyAction('cookStep',{eventId:c.cooking.id});else{const option=kitchenOptions()[choice];if(option)await cozyAction('cookStart',{dish:option.dish.id,addition:option.addition});else await cozyAction('pantryBuy');}return;}if(mode==='peace'){const response=['hug','play','sit','boundary'][choice%4];const ok=await cozyAction('peace',{response});if(ok&&response==='play'){mode='toys';choice=0;render();}return;}if(mode==='night')await cozyAction('nightToggle');}

async function living(command,body={}){if(busy)return;busy=true;generation++;try{const r=online?await api('living',{command,...body}):livingAction(state,command,body);if(r.error)throw Error(r.error);state=r.state;if(!online)save();speak(r.text);if(command==='draw')choice=1;if(command==='capture'){momentRecords=[...(state.daily?.photos||[])];choice=0;}if(r.effect){effect={kind:r.effect,started:Date.now(),until:Date.now()+3500};void audio.react(roomSounds[body.item]||({toy:'play'}[r.effect]||r.effect),state.species);}return true;}catch(e){fail(e.message);return false;}finally{busy=false;render();}}
async function sandboxAction(command,target,game){if(!online||busy)return;busy=true;try{const r=await api('sandbox',{command,target,game});if(mode!=='sandbox')return;state=r.state;sandboxPets=r.pets||[];sandboxScenes=r.scenes||[];sandboxSelfId=r.selfId||null;choice%=Math.max(1,sandboxPets.length*4);if(r.text)speak(r.text);if(!sandboxTimer)sandboxTimer=setInterval(()=>{if(mode==='sandbox'&&!busy&&!document.hidden)void sandboxAction('poll');},8000);}catch(e){fail(e.message);}finally{busy=false;render();}}
function drawSandbox(cv){if(detailedReady()){drawDetailedSandbox(cv,state,sandboxPets,Math.floor(choice/4),Date.now(),reduced,sandboxScenes,sandboxSelfId);return;}cv.width=192;cv.height=144;const c=cv.getContext('2d');c.imageSmoothingEnabled=false;c.fillStyle='#bfcba3';c.fillRect(0,0,192,144);c.fillStyle='#cfbd8e';c.fillRect(6,48,180,91);c.fillStyle='#8d7755';c.fillRect(4,139,184,4);const selected=Math.floor(choice/4),page=Math.floor(selected/8),visitors=sandboxPets.slice(page*8,page*8+8),peers=[{species:state.species,name:state.name,own:true},...visitors];const scene=socialScene(sandboxScenes);for(const [i,p]of peers.entries()){if(scene?.actors.includes(i===0?sandboxSelfId:p.id))continue;const layer=document.createElement('canvas');layer.width=128;layer.height=100;drawClassic(layer,p.species,Date.now(),{...(i===0?state:p.look),species:p.species,born:state.born,id:p.id||state.id,sleeping:false,napping:false,dead:false,world:{},cozy:i===0?state.cozy:p.look?.cozy||{wearing:{}}},false,true);const x=i===0?96:24+(i-1)%4*48,y=i===0?138:79+Math.floor((i-1)/4)*31;c.drawImage(layer,31,8,68,80,x-16,y-38,32,38);if(i>0&&selected===page*8+i-1){c.fillStyle='#526846';c.fillRect(x-3,y-43,6,3);}}if(scene)drawSocialScene(c,scene,[{id:sandboxSelfId,species:state.species,look:state},...sandboxPets],(p,x,y,h)=>{const layer=document.createElement('canvas');layer.width=128;layer.height=100;drawClassic(layer,p.species,Date.now(),{...p.look,species:p.species,portraitStage:p.look?.portraitStage||'Дорослий',sleeping:false,napping:false},false,true);c.drawImage(layer,31,8,68,80,x-h*.4,y-h,h*.8,h);},Date.now(),reduced);}


function smoothPose(target,frame,s){if(target.interaction){smoothScene={...target,id:s?.id,t:frame};return target;}if(!smoothScene||smoothScene.id!==s?.id||reduced){smoothScene={...target,id:s?.id,t:frame};return target;}const k=Math.min(1,Math.max(0,(frame-smoothScene.t)/(target.enriched?.mood==='sleepy'?1200:700)));for(const key of ['x','feet','scale'])smoothScene[key]+=(target[key]-smoothScene[key])*k;smoothScene.t=frame;return {...target,x:smoothScene.x,feet:smoothScene.feet,scale:smoothScene.scale};}

function renderInteractionControls(){const wrapper=$('#sandbox-controls');wrapper.hidden=mode!=='sandbox';if(mode!=='sandbox')return;const peers=$('#sandbox-peers'),actions=$('#sandbox-actions');peers.replaceChildren();actions.replaceChildren();sandboxPets.forEach((pet,i)=>{const button=document.createElement('button');button.type='button';button.className='sandbox-peer'+(Math.floor(choice/4)===i?' selected':'');button.textContent=pet.name;button.disabled=busy;button.setAttribute('aria-pressed',String(Math.floor(choice/4)===i));button.onclick=()=>{if(busy)return;choice=i*4;render();};peers.append(button);});const selected=sandboxPets[Math.floor(choice/4)];for(const [i,[command,label]]of [['hello','Привітатись'],['play','Грати'],['tease','Побурчати'],['avoid','Відійти']].entries()){const button=document.createElement('button');button.type='button';button.className='sandbox-action'+(choice%4===i?' selected':'');button.setAttribute('aria-label',label+(selected?' · '+selected.name:''));button.disabled=busy||!online||!selected;const text=document.createElement('span');text.textContent=label;button.append(actionIcon(command),text);button.onclick=()=>{if(busy||!selected)return;choice=Math.floor(choice/4)*4+i;void audio.unlock();void sandboxAction(command,selected.id);};actions.append(button);}for(const [game,label]of socialGames){const button=document.createElement('button');button.type='button';button.className='sandbox-action';button.textContent=label;button.disabled=busy||!online||!selected;button.onclick=()=>{if(!busy&&selected)void sandboxAction('play',selected.id,game);};actions.append(button);}}

async function toggleGraphics(){if(graphicsMode==='detailed'){setGraphicsMode('classic');smoothScene=null;speak('Оригінальна піксельна графіка.');render();return;}busy=true;speak('Готую сучасну графіку…');render();const ok=await loadDetailedAssets();busy=false;if(ok){setGraphicsMode('detailed');smoothScene=null;speak('Сучасна графіка.');}else fail('Зображення не завантажились. Спробуй ще раз.');document.querySelectorAll('.species-card canvas').forEach((canvas,i)=>draw(canvas,species[i].id,1000,null,true));render();}
if(graphicsMode==='detailed')void loadDetailedAssets().then(ok=>{if(!ok){if(typeof Image!=='undefined')fail('Не вдалося завантажити зображення. Перевідкрий гру, будь ласка.');return;}document.querySelectorAll('.species-card canvas').forEach((canvas,i)=>draw(canvas,species[i].id,1000,null,true));render();});

function paintPhotoScene(cv,p){if(detailedReady()){drawDetailedMain(cv,p,p.species,1000,true,{x:96,feet:128,scale:.9},null);return;}cv.width=192;cv.height=144;const c=cv.getContext('2d');drawExpandedRoom(c,p,1000,true);const layer=document.createElement('canvas');layer.width=128;layer.height=100;drawClassic(layer,p.species,1000,p,false,true);c.drawImage(layer,39,43,115,90);drawLighting(c,p);}
const capturedFrames=new Map();
$('#take-photo').onclick=async()=>{if(busy||!state)return;const frame=document.createElement('canvas');const source=$('#pet');frame.width=source.width;frame.height=source.height;frame.getContext('2d').drawImage(source,0,0);if(!await living('capture'))return;const row=momentRecords[0];if(row?.kind==='frame'){capturedFrames.set(row.id,frame);if(capturedFrames.size>12)capturedFrames.delete(capturedFrames.keys().next().value);}render();};
$('#share-photo').onclick=async()=>{const row=momentRecords[choice%Math.max(1,momentRecords.length)];if(!row||busy)return;try{const source=capturedFrames.get(row.id)||document.createElement('canvas');if(!capturedFrames.has(row.id))paintPhotoScene(source,row.pet);const result=await sharePostcard(postcard(source,row.comment,row.pet.name));if(result==='downloaded')speak('Фото збережене. Можна надіслати його в Telegram.');}catch(e){if(e.name!=='AbortError')fail(e.message);}};
let pendingRoomPlay=null,lastRoomDrag=0;
async function roomGameRequest(body){if(busy||loading){pendingRoomPlay=body;return;}await living('roomPlay',{...body,style:graphicsMode});}
function renderRoomGames(){const root=$('#room-game-controls');root.replaceChildren();root.hidden=mode!=='normal'||!roomAvailable(state);if(root.hidden)return;const run=state.living?.enrichment?.session;
 const add=(label,fn,active=false)=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.className=active?'selected':'';b.disabled=busy;b.onclick=()=>{void audio.unlock();fn();};root.append(b);};
 for(const [id,name]of roomGames)add(name,()=>void roomGameRequest({event:'start',kind:id}),run?.kind===id&&run.until>Date.now());
 if(run?.until>Date.now())add('↶ Закінчити',()=>void roomGameRequest({event:'stop'}));if(state.living?.enrichment?.traces?.length)add('Прибрати сліди',()=>void roomGameRequest({event:'clean'}));
}
setInterval(()=>{if(pendingRoomPlay&&!busy&&!loading&&mode==='normal'){const body=pendingRoomPlay;pendingRoomPlay=null;void roomGameRequest(body);}},150);
function uiBelongingChoices(s){const rows=belongingChoices(s);if(belongingItem)return rows.filter(row=>row.item.id===belongingItem);return ownedThings(s).map(item=>({item,action:['select','Відкрити дії']}));}
function roomOrigin(){return {fromX:smoothScene?.x??96,fromY:smoothScene?.feet??130};}
async function roomTap(x,y,long=false){
 if(!state||busy||loading||mode!=='normal')return;void audio.unlock();const run=state.living?.enrichment?.session;if(run?.until>Date.now()){await roomGameRequest({event:'tap',session:run.id,x,y});return;}
 if(state.cozy?.hide||state.lively?.secret?.kind==='box'){await living('leaveBox');return;}
 const id=roomHit(state,x,y,graphicsMode),pose=smoothScene||scenePose(state,0,true);
 const onPet=Math.abs(x-pose.x)<24&&y>pose.feet-48&&y<pose.feet+3;
 if(long&&onPet){dispatchRoomGesture({gesture:'pet'});return;}
 if(id&&long&&id!=='window'){belongingItem=id;choice=0;mode='belongings';render();return;}
 if(id==='window'){await living('secret',{spot:'window'});return;}
 if(id==='toy'){await roomGameRequest({event:'start',kind:'ball'});return;}
 if(id){await living(directRoomAction(id),{item:id,...roomOrigin()});return;}
 if(onPet)dispatchRoomGesture({gesture:'pet'});
}
function renderObjectControls(){
 const root=$('#object-controls');root.replaceChildren();root.hidden=!['belongings','activity','food','kitchen','roomStyle','decorate'].includes(mode);if(root.hidden)return;
 const button=(text,fn,selected=false)=>{const el=document.createElement('button');el.type='button';el.textContent=text;el.className=selected?'selected':'';el.disabled=busy;el.onclick=fn;root.append(el);};
 if(mode==='belongings'){const rows=uiBelongingChoices(state);for(const [i,row]of rows.entries())button(belongingItem?row.action[1]:row.item.name,()=>{if(busy)return;choice=i;if(!belongingItem){belongingItem=row.item.id;choice=0;render();}else void cozyOK();},i===choice);if(belongingItem)button('← Усі речі',()=>{belongingItem=null;choice=0;render();});return;}
 if(mode==='activity'){for(const [i,a]of activities.entries())button(a.id==='groom'?groomName(state):a.name,()=>{if(busy)return;choice=i;render();},choice===i);button('♡ Погладити',async()=>{mode='normal';render();await action('pet');});button('♡ Помиритися',async()=>{mode='normal';render();await cozyAction('peace',{response:'hug'});});return;}
 if(mode==='food'||mode==='kitchen')button(mode==='food'?'♨ Приготувати разом':'← Годування',()=>{mode=mode==='food'?'kitchen':'food';choice=0;render();});
 if(mode==='roomStyle'||mode==='decorate')button(mode==='roomStyle'?'⌂ Розставити меблі':'← Шпалери та світло',()=>{mode=mode==='roomStyle'?'decorate':'roomStyle';choice=0;render();});
}
$('#pet').addEventListener('click',event=>{if(Date.now()<suppressRoomClick||!state||busy||mode!=='normal')return;const rect=$('#pet').getBoundingClientRect();void roomTap((event.clientX-rect.left)/rect.width*192,(event.clientY-rect.top)/rect.height*144);});

function renderJournalCanvas(cv){if(!state)return;const j=ensureJournal(state);if(mode==='drawings'){const row=j.drawings[choice-1];cv.width=192;cv.height=144;const c=cv.getContext('2d');c.clearRect(0,0,192,144);if(row)drawDoodle(c,row);else{c.fillStyle='#f0e2bf';c.fillRect(0,0,192,144);c.fillStyle='#65735b';c.font='bold 10px monospace';c.fillText('ОК — НАМАЛЮВАТИ',36,78);}return;}if(mode==='dreamgame'){cv.width=384;cv.height=288;const c=cv.getContext('2d');c.save();c.scale(2,2);drawDreamScene(c,state,j.dreamRun,choice%3,(x,y,h)=>{const p={...state,sleeping:false,napping:false,world:{},portraitStage:stage(state)};if(detailedReady())drawDetailedPet(c,p,p.species,x,y,h,null,Date.now(),reduced);else{const layer=document.createElement('canvas');layer.width=128;layer.height=100;drawClassic(layer,p.species,Date.now(),p,false,true);c.drawImage(layer,31,8,68,80,x-h*.4,y-h,h*.8,h);}},Date.now(),reduced,detailedReady()?drawDetailedDreamProp:null);c.restore();return;}if(mode==='together'){const pos=scenePose(state,Date.now(),reduced);if(detailedReady()){drawDetailedMain(cv,state,state.species,Date.now(),reduced,detailedPose(state,pos),null);}else{cv.width=192;cv.height=144;const c=cv.getContext('2d');drawExpandedRoom(c,state,Date.now(),reduced);const layer=document.createElement('canvas');layer.width=128;layer.height=100;drawClassic(layer,state.species,Date.now(),state,false,true);const w=128*pos.scale,h=100*pos.scale;c.drawImage(layer,pos.x-w/2,pos.feet-h*.85,w,h);drawLively(c,state,pos,Date.now(),reduced);}return;}paintPhotoScene(cv,state);}
function renderJournalChoice(cv){const j=ensureJournal(state),title=$('#choice-title'),detail=$('#choice-detail');cv.hidden=false;renderJournalCanvas(cv);if(mode==='drawings'){const row=j.drawings[choice-1];title.textContent=row?.title||'МАЛЮНКИ МОГО ДРУГА';detail.textContent=row?'«'+row.comment+'»\n'+(j.pinned===row.id?'Висить у кімнаті. ОК — зняти.':'ОК — повісити на стіну.')+'\n← → малюнки · окрема кнопка — зберегти PNG.':'ОК — попросити новий малюнок. ← → альбом. Пет також малює сам із часом.';return;}if(mode==='keepsakes'){title.textContent='КІМНАТА ДОРОСЛІШАЄ ЗІ МНОЮ';detail.textContent='Позначки зросту: '+(j.marks.map(m=>m.stage).join(' → ')||'Ще чекаємо вилуплення.')+'\nМалюнків: '+j.drawings.length+(j.familyArt?' · є сімейний малюнок.':'')+'\nНа улюбленій іграшці з’являються латки після спільних ігор.';return;}if(mode==='quirks'){title.textContent='МОЯ СІМЕЙНА ЗВИЧКА';detail.textContent=quirkNames[j.quirk.id]+(j.quirk.from?'\nУспадковано від '+j.quirk.from+'.':'\nМаленька особливість нашого першого покоління.')+'\nПередається наступному поколінню разом зі спогадом.';return;}if(mode==='courage'){const fear=Object.keys(fearNames)[choice%3];title.textContent='СМІЛИВІСТЬ: '+fearNames[fear].toUpperCase();detail.textContent='Довіра: '+j.courage[fear]+'/3\n'+(j.courage[fear]>=3?'Ми вже впорались. Фото є в альбомі.':'ОК — один спокійний крок. Можна зупинитися будь-коли.')+'\n← → купання / гроза / знайомство. Без штрафів.';return;}if(mode==='together'){title.textContent='ПРОСТО ПОБУТИ ПОРУЧ';detail.textContent=j.together?'Я тут. Без таймера, завдань і нагород.\nОК або ↶ — повернутися до справ.':'ОК — сісти поруч. Без таймера й обов’язків.';return;}if(mode==='dreamgame'){title.textContent=dreamTheme(state).title;detail.textContent=state.sleeping||state.napping?(j.dreamRun?dreamTheme(state).hint+'\n← → хмаринка · ОК стрибок · '+j.dreamRun.hits+'/5. Без штрафів.':'ОК — зазирнути у сон. Пет продовжить відпочивати.'):'Пет зараз не спить. Поклади його спати через Турбота → Сон.';}}
async function journalOK(){if(mode==='drawings'){const row=state.journal?.drawings?.[choice-1];await living(row?'pinDrawing':'draw',row?{drawing:row.id}:{});return;}if(mode==='courage'){await living('courage',{fear:Object.keys(fearNames)[choice%3]});return;}if(mode==='together'){await living('together');return;}if(mode==='dreamgame'){const run=state.journal?.dreamRun;await living(run?'dreamTurn':'dreamStart',run?{eventId:run.id,turn:run.turn,lane:choice%3}:{});return;}}
$('#save-drawing').onclick=async()=>{const row=state?.journal?.drawings?.[choice-1];if(!row||busy)return;try{const cv=document.createElement('canvas');cv.width=192;cv.height=144;drawDoodle(cv.getContext('2d'),row);const result=await sharePostcard(postcard(cv,row.comment,state.name));if(result==='downloaded')speak('Малюнок збережений у PNG.');}catch(e){if(e.name!=='AbortError')fail(e.message);}};
let roomPointer=null,suppressRoomClick=0;
$('#pet').addEventListener('pointerdown',e=>{if(!state||mode!=='normal')return;try{$('#pet').setPointerCapture?.(e.pointerId);}catch{}const box=$('#pet').getBoundingClientRect();roomPointer={x:(e.clientX-box.left)/box.width*192,y:(e.clientY-box.top)/box.height*144,at:Date.now(),id:e.pointerId,petX:(smoothScene||scenePose(state,0,true)).x,petFeet:(smoothScene||scenePose(state,0,true)).feet,path:0,turns:0,lastX:(e.clientX-box.left)/box.width*192,lastY:(e.clientY-box.top)/box.height*144,sign:0};});
$('#pet').addEventListener('pointermove',e=>{const start=roomPointer;if(!start||start.id!==e.pointerId||mode!=='normal')return;const box=$('#pet').getBoundingClientRect(),x=Math.max(0,Math.min(192,(e.clientX-box.left)/box.width*192)),y=Math.max(0,Math.min(144,(e.clientY-box.top)/box.height*144)),dx=x-start.lastX,dy=y-start.lastY,sign=Math.sign(dx);start.path+=Math.hypot(dx,dy);if(sign&&start.sign&&sign!==start.sign)start.turns++;if(sign)start.sign=sign;start.lastX=x;start.lastY=y;const run=state?.living?.enrichment?.session;if(run?.until>Date.now()&&Date.now()-lastRoomDrag>300){lastRoomDrag=Date.now();void roomGameRequest({event:'move',session:run.id,x,y,dx,dy});}});
$('#pet').addEventListener('pointercancel',()=>{roomPointer=null;});
$('#pet').addEventListener('pointerup',e=>{const start=roomPointer;roomPointer=null;if(!start||mode!=='normal'||!state||start.id!==e.pointerId)return;const box=$('#pet').getBoundingClientRect(),x=Math.max(0,Math.min(192,(e.clientX-box.left)/box.width*192)),y=Math.max(0,Math.min(144,(e.clientY-box.top)/box.height*144)),dist=Math.hypot(x-start.x,y-start.y),pose=smoothScene||scenePose(state,0,true),age=stage(state),h=age==='Малюк'?27:age==='Дитина'?43:60,onPet=Math.abs(start.x-(start.petX??pose.x))<(age==='Малюк'?15:24)&&start.y>(start.petFeet??pose.feet)-h&&start.y<(start.petFeet??pose.feet)+3;suppressRoomClick=Date.now()+700;
 const run=state.living?.enrichment?.session;if(run?.until>Date.now()){void roomGameRequest({event:dist<8?'tap':'move',session:run.id,x,y,dx:x-start.x,dy:y-start.y});return;}
 if(onPet&&start.path>10){void roomGameRequest({event:'touch',kind:start.turns>=2||start.path/Math.max(1,Date.now()-start.at)>.13?'tickle':'stroke'});return;}
 if(onPet&&dist<8&&Math.hypot(x-pose.x,y-(pose.feet-h*.38))<9){void roomGameRequest({event:'touch',kind:'nose'});return;}
 if(Math.abs(x-start.x)>14&&start.y>=66){dispatchRoomGesture({gesture:'ball',x:Math.max(0,Math.min(1,x/192)),from:Math.max(0,Math.min(1,start.x/192))});return;}if(dist<8)void roomTap(x,y,Date.now()-start.at>=450);});

function styleOptions(){return Object.entries(roomStyles).flatMap(([kind,items])=>items.map((_,i)=>[kind,i]));}
let walletInfo=null,lastGiftOp=null;
async function walletRequest(command,details={}){if(busy)return;if(!online){speak('Гаманець працює через Telegram.');return;}busy=true;generation++;render();try{const r=await api('wallet',{command,...details});walletInfo=r.wallet;if(r.state)state=r.state;if(r.text)speak(r.text);if(command==='gift')lastGiftOp=null;}catch(e){if(command==='gift'&&e.message.includes('анульовано'))lastGiftOp=null;fail(e.message);}finally{busy=false;render();}}
function renderWallet(){const c=$('#wallet-controls');c.replaceChildren();const input=document.createElement('input');input.type='number';input.min='1';input.max='1000000000000';input.value='100';input.id='wallet-amount';input.setAttribute('aria-label','Сума монет');c.append(input);const add=(label,fn,disabled=false)=>{const b=document.createElement('button');b.type='button';b.textContent=label;b.disabled=busy||disabled;b.onclick=fn;c.append(b);};const amount=()=>Number(input.value);add('У гаманець',()=>void walletRequest('move',{direction:'deposit',amount:amount()}));add('У кишеню пета',()=>void walletRequest('move',{direction:'withdraw',amount:amount()}));add('Створити подарунок',()=>{const n=amount();if(!lastGiftOp||lastGiftOp.amount!==n)lastGiftOp={op:walletOperationId(),amount:n};void walletRequest('gift',lastGiftOp);});if(walletInfo?.balance>0)add('Усі монети — для покупок',()=>void walletRequest('move',{direction:'withdraw',amount:walletInfo.balance}));if(walletInfo?.owner)add('+ 1 000 000 монет',()=>void walletRequest('refill'));const code=document.createElement('input');code.type='text';code.placeholder='ABCD-EFGH-JK';code.id='gift-code';code.setAttribute('aria-label','Код подарунка');c.append(code);add('Забрати подарунок',()=>void walletRequest('redeem',{code:code.value}));for(const gift of (walletInfo?.gifts||[]).filter(g=>g.status!=='redeemed')){const row=document.createElement('p');row.textContent=gift.amount+' монет · '+({issued:'Одноразовий код: ',redeemed:'Використано: ',revoked:'Анульовано: ',reserved:'Готується: '}[gift.status]||'Код: ')+gift.code;c.append(row);add('Поділитися кодом',async()=>{try{if(navigator.share)await navigator.share({text:'Тобі '+gift.amount+' монет у РААААРРРРРРАГОЧІ! У грі: Дім → Гаманець → Забрати подарунок. Код: '+gift.code});else if(navigator.clipboard){await navigator.clipboard.writeText(gift.code);speak('Код скопійовано. Надішли його другу.');}else{code.value=gift.code;code.select();speak('Виділив код. Скопіюй і надішли другу.');}}catch(e){if(e.name!=='AbortError')fail(e.message);}},gift.status!=='issued');}}

let pendingRoomGesture=null;function dispatchRoomGesture(payload){if(busy||loading){pendingRoomGesture=payload;return;}void living('gesture',payload);}setInterval(()=>{if(pendingRoomGesture&&!busy&&!loading&&mode==='normal'){const payload=pendingRoomGesture;pendingRoomGesture=null;dispatchRoomGesture(payload);}},150);

function walletOperationId(){if(crypto.randomUUID)return crypto.randomUUID();const bytes=crypto.getRandomValues(new Uint8Array(16));bytes[6]=(bytes[6]&15)|64;bytes[8]=(bytes[8]&63)|128;const h=[...bytes].map(n=>n.toString(16).padStart(2,'0')).join('');return h.slice(0,8)+'-'+h.slice(8,12)+'-'+h.slice(12,16)+'-'+h.slice(16,20)+'-'+h.slice(20);}

let lastChatterId=null,lastChatterSound=0;setInterval(()=>{if(!state||mode!=='normal'||busy||loading||document.hidden||effectActive())return;const bit=chatter(state);if(!bit||bit.id===lastChatterId||!idleSpeechDue(state,lastSpeech))return;lastChatterId=bit.id;const spoken=speak(bit.text);if(spoken&&bit.kind==='hum'&&Date.now()-lastChatterSound>300000){lastChatterSound=Date.now();void audio.react('music'+bit.tune,state.species);}},2000);
